#include <WiFi.h>
#include <HTTPClient.h>

const char* WIFI_SSID = "meh";
const char* WIFI_PASSWORD = "haalloooo";

const char* FIREBASE_URL =
  "https://smart-energy-monitor-a8d80-default-rtdb.asia-southeast1.firebasedatabase.app";

void setup() {
  Serial.begin(115200);

  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

  Serial.print("Connecting to WiFi");

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println();
  Serial.println("WiFi connected!");
  Serial.println(WiFi.localIP());
}

void loop() {

  int load = 800;

  if (WiFi.status() == WL_CONNECTED) {

    HTTPClient http;

    String url = String(FIREBASE_URL) + "/load.json";

    http.begin(url);
    http.addHeader("Content-Type", "application/json");

    String data = String(load);

    int responseCode = http.PUT(data);

    Serial.print("Firebase response: ");
    Serial.println(responseCode);

    http.end();
  }

  delay(2000);
}
